import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import ts from 'typescript';
import {chromium,expect} from '@playwright/test';
import sharp from 'sharp';
const root=new URL('./evidence/probe2/',import.meta.url),a=await readFile('tests/fixtures/art-water-0.png'),b=await readFile('tests/fixtures/art-water-1.png');
const hash=x=>createHash('sha256').update(x).digest('hex'),path='/api/projects/owned/recipes/fixed/processed?frame=0';
const events=[],reads=[];let held;
const html=`<body><script>window.load=async function(path='${path}'){let r=await fetch(path,{cache:'no-store'}),b=await r.arrayBuffer(),i=new Image();i.id='current';i.src=URL.createObjectURL(new Blob([b],{type:'image/png'}));i.dataset.sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');await i.decode();document.getElementById('current')?.remove();document.body.append(i);return i.dataset.sha;};if(location.pathname==='/auto')window.ready=window.load();</script></body>`;
const server=createServer((req,res)=>{if(req.url.startsWith('/api/')){reads.push(req.url);res.writeHead(200,{'content-type':'image/png','cache-control':'no-store'});if(req.url.includes('hold')){held=res;res.write(a.subarray(0,8));}else res.end(req.url.includes('frame=1')?b:a);}else res.end(html);});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;
const compile=async s=>{const js=ts.transpileModule(s,{compilerOptions:{target:ts.ScriptTarget.ES2023,module:ts.ModuleKind.ESNext}}).outputText;return (await import('data:text/javascript;base64,'+Buffer.from(js).toString('base64'))).ReceivedResources;};
const New=await compile(await readFile('apps/api/tests/studio/received-resources.ts','utf8')),Old=await compile(execFileSync('git',['show','a8f23ef5ad218278447cca2d22c7014adb16ca02:apps/api/tests/studio/received-resources.ts'],{encoding:'utf8'}));
const browser=await chromium.launch();
const results=[];async function save(n,x){await writeFile(new URL(n,root),JSON.stringify(x,null,2)+'\n');}
async function rendered(page,capture,url=origin+path){let sha=await page.locator('#current').getAttribute('data-sha');let entry=capture.find(url,sha);assert.ok(entry,'current required completed actual browser body missing');const decoded=await sharp(entry.bytes).ensureAlpha().raw().toBuffer({resolveWithObject:true});assert.deepEqual([decoded.info.width,decoded.info.height],[96,144]);let canvas=await page.locator('#current').evaluate(i=>{let c=document.createElement('canvas');c.width=96;c.height=144;let x=c.getContext('2d');x.drawImage(i,0,0);return [...x.getImageData(0,0,96,144).data];});assert.deepEqual(Buffer.from(canvas),decoded.data);return {id:entry.id,sha,document:entry.document,transport:entry.transport};}
async function fixture(name,Class,fn){const page=await browser.newPage(),c=new Class(page,origin,'owned'),start=reads.length;try{if(c.observeDocuments)await c.observeDocuments();await page.goto(origin);await page.evaluate('window.load()');await expect.poll(()=>c.find(origin+path,hash(a))?.sha).toBe(hash(a));await fn(page,c);results.push({name,result:'PASS',reads:reads.length-start});}finally{await save('probe-'+name+'.json',{reads:reads.slice(start),records:c.snapshot()});c.dispose();await page.close();}}
try{
 const session=await browser.newBrowserCDPSession();await save('browser-identity.json',{version:browser.version(),protocol:await session.send('Browser.getVersion'),cache:process.env.PLAYWRIGHT_BROWSERS_PATH,defaultLaunch:true});await session.detach();
 await fixture('old-same-document',Old,async(page,c)=>{const before=await rendered(page,c),n=reads.length;await page.evaluate(()=>history.pushState({},'','#push'));let actual;try{await rendered(page,c);throw Error('Old helper did not reproduce');}catch(e){assert.match(e.message,/current required completed actual browser body missing/);actual=e.stack;}
 await writeFile(new URL('old-controlled-failure.txt',root),actual+'\n');assert.equal(reads.length,n);assert.equal(await page.locator('#current').getAttribute('data-sha'),before.sha);await save('old-controlled-result.json',{classification:'EXPECTED_OLD_HELPER_FAILURE_CONTROLLED_MECHANISM_NOT_CI5_CAUSE',before,after:c.snapshot(),sameDOMHash:before.sha,extraRequests:0});});
 await fixture('new-same-document',New,async(page,c)=>{const before=await rendered(page,c),n=reads.length;for(const action of ['push','replace','hash','path']){await page.evaluate(action=>{if(action==='push')history.pushState({},'','#push');if(action==='replace')history.replaceState({},'','#replace');if(action==='hash')location.hash='hash-direct';if(action==='path')history.pushState({},'','/same-document-path');},action);assert.deepEqual(await rendered(page,c),before);}assert.equal(reads.length,n);await page.screenshot({path:new URL('same-document-actual.png',root).pathname});});
 await fixture('failed-navigation-and-reload',New,async(page,c)=>{const before=await rendered(page,c);await page.route('**/cancel',r=>r.abort('aborted'));await assert.rejects(page.goto(origin+'/cancel'));assert.deepEqual(await rendered(page,c),before);await page.unroute('**/cancel');await page.reload();assert.equal(c.find(origin+path,hash(a)),undefined);await page.evaluate('window.load()');await expect.poll(()=>c.find(origin+path,hash(a))?.id).not.toBe(before.id);assert.notEqual((await rendered(page,c)).document,before.document);});
 await fixture('iframe-owner-and-no-receipt',New,async(page,c)=>{const count=c.snapshot().length;await page.evaluate(async()=>{let f=document.createElement('iframe');f.src='/auto';document.body.append(f);await new Promise(r=>f.onload=r);await f.contentWindow.ready;});assert.equal(c.snapshot().length,count);const late=new New(page,origin,'owned');try{await late.observeDocuments();await assert.rejects(rendered(page,late),/actual browser body missing/);}finally{late.dispose();}assert.throws(()=>c.find(origin+path.replace('/owned/','/other/'),hash(a)));assert.equal(c.find(origin+path.replace('frame=0','frame=1'),hash(a)),undefined);assert.equal(c.find(origin+path,hash(b)),undefined);});
 await fixture('late-body-across-commit',New,async(page,c)=>{const oldDoc=(await rendered(page,c)).document;const response=page.waitForResponse(origin+path+'&hold=1');await page.evaluate(p=>{window.pending=window.load(p).catch(e=>e.name);},path+'&hold=1');await response;await page.goto(origin+'/new-document');held.end(a.subarray(8));await expect.poll(()=>c.snapshot().find(r=>r.url.includes('hold'))?.state).toBe('received');assert.equal(c.find(origin+path,hash(a)),undefined);assert.equal(c.find(origin+path+'&hold=1',hash(a)),undefined);await page.evaluate('window.load()');await expect.poll(()=>c.find(origin+path,hash(a))?.sha).toBe(hash(a));assert.notEqual((await rendered(page,c)).document,oldDoc);});
 await fixture('automatic-first-request-commit-order',New,async(page,c)=>{let n=reads.length,docs=[];for(let k=0;k<24;k++){await page.goto(origin+'/auto');await page.evaluate('window.ready');await expect.poll(()=>c.find(origin+path,hash(a))?.sha).toBe(hash(a));docs.push((await rendered(page,c)).document);}assert.equal(new Set(docs).size,24);assert.equal(reads.length-n,24);await save('automatic-commit-order.json',{iterations:24,documents:docs,extraPNGRequests:0,events:'real immediate inline-script fetch after each committed document; no sleeps'});});
 await save('probe-summary.json',{results,assertions:'real HTTP bytes -> response.body SHA -> image.decode -> Canvas RGBA vs independent Sharp; event-driven only',CI5Cause:'UNVERIFIED_NO_CAPTURE_ARTIFACT'});console.log(JSON.stringify(results));
}finally{await browser.close();held?.destroy();server.closeAllConnections();await new Promise(r=>server.close(r));}
